-- Blind Eyes only. Run the whole file in Supabase SQL Editor as postgres.
begin;
create schema if not exists blind_private;
revoke all on schema blind_private from public, anon, authenticated;
create table blind_private.topics (
 id uuid primary key default gen_random_uuid(), source_id text unique not null,
 payload jsonb not null, answers text[] not null
);
create table public.be_rooms (
 id uuid primary key default gen_random_uuid(), topic_id uuid not null references blind_private.topics(id),
 status text not null default 'playing' check(status in ('playing','finished','closed')),
 attempts integer not null default 0, success boolean, last_answer text,
 version integer not null default 0, created_at timestamptz not null default now()
);
create table public.be_members (
 room_id uuid not null references public.be_rooms(id), user_id uuid not null references auth.users(id),
 role text not null check(role in ('describer','guesser')), seen_at timestamptz not null default now(), left_at timestamptz,
 primary key(room_id,user_id), unique(room_id,role)
);
create unique index be_one_live_room on public.be_members(user_id) where left_at is null;
create table public.be_queue (
 user_id uuid primary key references auth.users(id), topic_id uuid not null references blind_private.topics(id),
 preferred_role text not null check(preferred_role in ('describer','guesser')),
 joined_at timestamptz not null default now(), seen_at timestamptz not null default now()
);
create index be_queue_topic on public.be_queue(topic_id,joined_at);
create table public.be_messages (
 id bigint generated always as identity primary key, room_id uuid not null references public.be_rooms(id),
 sender_id uuid not null references auth.users(id), body text not null check(char_length(body) between 1 and 2000),
 request_id uuid not null, created_at timestamptz not null default now(), unique(sender_id,request_id)
);
create index be_messages_room on public.be_messages(room_id,id);
create table blind_private.guesses (
 room_id uuid not null references public.be_rooms(id), request_id uuid not null, user_id uuid not null,
 primary key(room_id,request_id)
);
create function blind_private.norm(v text) returns text language sql immutable set search_path='' as $$
 select regexp_replace(lower(normalize(coalesce(v,''),NFKD)), '[^[:alnum:]]', '', 'g')
$$;
create function public.be_is_member(p_room uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.be_members where room_id=p_room and user_id=auth.uid() and left_at is null)
$$;
alter table public.be_rooms enable row level security;
alter table public.be_members enable row level security;
alter table public.be_queue enable row level security;
alter table public.be_messages enable row level security;
create policy be_room_read on public.be_rooms for select to authenticated using(public.be_is_member(id));
create policy be_member_read on public.be_members for select to authenticated using(public.be_is_member(room_id));
create policy be_queue_read on public.be_queue for select to authenticated using(user_id=auth.uid());
create policy be_message_read on public.be_messages for select to authenticated using(public.be_is_member(room_id));
revoke all on public.be_rooms,public.be_members,public.be_queue,public.be_messages from anon,authenticated;
grant select on public.be_rooms,public.be_members,public.be_queue,public.be_messages to authenticated;

create function public.be_topics() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'comment',payload->>'comment','stars',payload->'stars') order by source_id),'[]'::jsonb) from blind_private.topics where auth.uid() is not null
$$;
-- All lifecycle writes take the same transaction lock. For ~10 players this is
-- cheap and makes join/cancel/expiry/guess races serial and deterministic.
create function blind_private.cleanup() returns void language plpgsql set search_path='' as $$
begin
 delete from public.be_queue where seen_at < now()-interval '65 seconds';
 update public.be_rooms r set status='closed',version=version+1 where status<>'closed' and exists
 (select 1 from public.be_members m where m.room_id=r.id and m.left_at is null and m.seen_at<now()-interval '150 seconds');
 update public.be_members m set left_at=now() where left_at is null and exists(select 1 from public.be_rooms r where r.id=m.room_id and r.status='closed');
end $$;
create function public.be_leave() returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 perform pg_advisory_xact_lock(82471001);
 delete from public.be_queue where user_id=auth.uid();
 update public.be_rooms r set status='closed',version=version+1 where status<>'closed' and exists
 (select 1 from public.be_members m where m.room_id=r.id and m.user_id=auth.uid() and m.left_at is null);
 update public.be_members m set left_at=now() where left_at is null and exists(select 1 from public.be_rooms r where r.id=m.room_id and r.status='closed');
end $$;
create function public.be_match(p_topic uuid,p_role text) returns jsonb language plpgsql security definer set search_path='' as $$
declare partner public.be_queue; rid uuid; myrole text;
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 if p_role not in ('describer','guesser') or p_role is null then raise exception 'Invalid role'; end if;
 perform pg_advisory_xact_lock(82471001);
 perform blind_private.cleanup();
 if not exists(select 1 from blind_private.topics where id=p_topic) then raise exception 'Unknown topic'; end if;
 select m.room_id,m.role into rid,myrole from public.be_members m join public.be_rooms r on r.id=m.room_id
 where m.user_id=auth.uid() and m.left_at is null and r.status<>'closed';
 if rid is not null then return jsonb_build_object('room_id',rid,'role',myrole); end if;
 -- No cross-topic matching, including when both players prefer the same role.
 select * into partner from public.be_queue where topic_id=p_topic and user_id<>auth.uid() order by joined_at,user_id limit 1;
 if partner.user_id is null then
 insert into public.be_queue(user_id,topic_id,preferred_role) values(auth.uid(),p_topic,p_role)
 on conflict(user_id) do update set topic_id=excluded.topic_id,preferred_role=excluded.preferred_role,
 joined_at=case when be_queue.topic_id=excluded.topic_id then be_queue.joined_at else now() end,seen_at=now();
 return jsonb_build_object('waiting',true);
 end if;
 insert into public.be_rooms(topic_id) values(p_topic) returning id into rid;
 myrole=case when partner.preferred_role='describer' then 'guesser' else 'describer' end;
 insert into public.be_members(room_id,user_id,role) values(rid,partner.user_id,partner.preferred_role),(rid,auth.uid(),myrole);
 delete from public.be_queue where user_id in(auth.uid(),partner.user_id);
 return jsonb_build_object('room_id',rid,'role',myrole);
end $$;
create function public.be_snapshot(p_room uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.be_rooms; a jsonb; myrole text; n integer; unlocked integer; safe jsonb;
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 perform pg_advisory_xact_lock(82471001);
 perform blind_private.cleanup();
 select role into myrole from public.be_members where room_id=p_room and user_id=auth.uid() and left_at is null;
 if myrole is null then return jsonb_build_object('closed',true); end if;
 update public.be_members set seen_at=now() where room_id=p_room and user_id=auth.uid();
 select * into r from public.be_rooms where id=p_room;
 select payload into a from blind_private.topics where id=r.topic_id;
 n=(a->>'stars')::integer;
 unlocked=least(n,r.attempts);
 safe=jsonb_build_object('stars',n,'comment',a->>'comment','clues',
 (select jsonb_agg(case when i>=5-n and i<5-n+unlocked then a->'clues'->i else 'null'::jsonb end order by i) from generate_series(0,4) i));
 if unlocked>=n then safe=safe || jsonb_build_object('area',a->'area'); end if;
 if myrole='describer' or r.status='finished' then
 safe=safe || jsonb_build_object('image',a->>'image','crop',a->'crop','imageWidth',a->'imageWidth','imageHeight',a->'imageHeight','imageBounds',a->'imageBounds');
 end if;
 if r.status='finished' then safe=a; end if;
 return jsonb_build_object('id',r.id,'topic_id',r.topic_id,'status',r.status,'attempts',r.attempts,
 'success',r.success,'last_answer',r.last_answer,'role',myrole,'art',safe,'version',r.version);
end $$;
create function public.be_guess(p_room uuid,p_answer text,p_request uuid) returns void language plpgsql security definer set search_path='' as $$
declare r public.be_rooms; a jsonb; ok boolean; n integer;
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 perform pg_advisory_xact_lock(82471001);
 perform blind_private.cleanup();
 if not exists(select 1 from public.be_members where room_id=p_room and user_id=auth.uid() and role='guesser' and left_at is null) then raise exception 'Only the guesser may submit'; end if;
 if exists(select 1 from blind_private.guesses where room_id=p_room and request_id=p_request) then return; end if;
 select * into r from public.be_rooms where id=p_room for update;
 if r.status<>'playing' then raise exception 'Round is no longer playing'; end if;
 if char_length(trim(p_answer)) not between 1 and 200 or blind_private.norm(p_answer)='' then raise exception 'Invalid answer'; end if;
 select payload,exists(select 1 from unnest(answers) x where blind_private.norm(x)=blind_private.norm(p_answer)) into a,ok from blind_private.topics where id=r.topic_id;
 n=r.attempts+1;
 insert into blind_private.guesses values(p_room,p_request,auth.uid());
 update public.be_rooms set attempts=n,last_answer=trim(p_answer),success=case when ok or n>=(a->>'stars')::integer+1 then ok else null end,
 status=case when ok or n>=(a->>'stars')::integer+1 then 'finished' else 'playing' end,version=version+1 where id=p_room;
end $$;
create function public.be_send(p_room uuid,p_body text,p_request uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 perform pg_advisory_xact_lock(82471001);
 perform blind_private.cleanup();
 if not public.be_is_member(p_room) or not exists(select 1 from public.be_rooms where id=p_room and status<>'closed') then raise exception 'Room is closed'; end if;
 if char_length(trim(p_body)) not between 1 and 2000 then raise exception 'Message must be 1–2000 characters'; end if;
 insert into public.be_messages(room_id,sender_id,body,request_id) values(p_room,auth.uid(),trim(p_body),p_request) on conflict(sender_id,request_id) do nothing;
end $$;
-- No RPC has implicit PUBLIC/anon execute permission.
revoke all on all functions in schema blind_private from public,anon,authenticated;
revoke all on function public.be_is_member(uuid),public.be_topics(),public.be_leave(),public.be_match(uuid,text),public.be_snapshot(uuid),public.be_guess(uuid,text,uuid),public.be_send(uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.be_is_member(uuid),public.be_topics(),public.be_leave(),public.be_match(uuid,text),public.be_snapshot(uuid),public.be_guess(uuid,text,uuid),public.be_send(uuid,text,uuid) to authenticated;
do $$ begin
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='be_rooms') then alter publication supabase_realtime add table public.be_rooms; end if;
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='be_messages') then alter publication supabase_realtime add table public.be_messages; end if;
end $$;

insert into blind_private.topics(source_id,payload,answers) values('D-01-01','{"id":"D-01-01","metId":435809,"title":"The Harvesters","titleZh":"收割者","artist":"Pieter Bruegel the Elder","date":"1565","medium":"Oil on oak","category":"Architecture","area":1,"description":"A layered countryside scene of harvest work, a shared meal, distant fields and tiny buildings. The landscape belongs to a seasonal cycle.","image":"assets/artworks/BE-001.jpg","imageRemote":"https://images.metmuseum.org/CRDImages/ep/original/DP119115.jpg","source":"https://www.metmuseum.org/art/collection/search/435809","imageRights":"Public Domain — The Metropolitan Museum of Art","imageWidth":3811,"imageHeight":2809,"imageBounds":{"x":0.008,"y":0.008,"w":0.985,"h":0.985},"surfaceNote":"Crop percentages refer to this configured artwork image surface, excluding the photographed frame and calibration strips.","artworkId":"BE-001","variant":0,"workIndex":0,"comment":"A little place beyond the noise","reflection":"A little place beyond the noise. It makes me think of things I usually walk past without noticing. A small part can carry the feeling of a whole place.","crop":{"x":0.4,"y":0.44,"w":0.07,"h":0.06},"ratio":0.004200000000000001,"stars":5,"clues":["Think about the unnoticed parts of an ordinary day, rather than a famous figure.","This is a small part of a layered outdoor scene.","Look for repeating edges, small divisions and changes between light and shadow.","The selected detail lies in the upper left part of its original composition. Compare the nearby edges and surfaces.","Area 1 — upper left"],"commentType":"Original fictional visitor reflection for this prototype","cropTarget":"Non-identifying small surface detail"}'::jsonb,ARRAY['BE-001','The Harvesters','收割者']);
